function minCutImpl(s) {
  const n=s.length;
  const isPalin=Array.from({length:n},()=>new Array(n).fill(false));
  for(let i=0;i<n;i++)isPalin[i][i]=true;
  for(let i=0;i<n-1;i++)isPalin[i][i+1]=s[i]===s[i+1];
  for(let len=3;len<=n;len++)
    for(let i=0;i<=n-len;i++){const j=i+len-1;isPalin[i][j]=s[i]===s[j]&&isPalin[i+1][j-1];}
  const dp=new Array(n).fill(Infinity);
  for(let i=0;i<n;i++){
    if(isPalin[0][i])dp[i]=0;
    else for(let j=1;j<=i;j++)if(isPalin[j][i])dp[i]=Math.min(dp[i],dp[j-1]+1);
  }
  return dp[n-1];
}

