function robImpl(root) {
  function dfs(node){
    if(!node)return[0,0];
    const[lr,ls]=dfs(node.left),[rr,rs]=dfs(node.right);
    return[node.val+ls+rs,Math.max(lr,ls)+Math.max(rr,rs)];
  }
  return Math.max(...dfs(root));
}

function minCameraCoverImpl(root) {
  let cameras=0;
  function dfs(node){
    if(!node)return 2;
    const l=dfs(node.left),r=dfs(node.right);
    if(l===0||r===0){cameras++;return 1;}
    if(l===1||r===1)return 2;
    return 0;
  }
  if(dfs(root)===0)cameras++;
  return cameras;
}

