function tspImpl(dist) {
  const n=dist.length,FULL=(1<<n)-1,INF=Infinity;
  const dp=Array.from({length:1<<n},()=>new Array(n).fill(INF));
  dp[1][0]=0;
  for(let mask=1;mask<=FULL;mask++)for(let i=0;i<n;i++){
    if(dp[mask][i]===INF||!(mask&(1<<i)))continue;
    for(let j=0;j<n;j++){if(mask&(1<<j))continue;const nm=mask|(1<<j);dp[nm][j]=Math.min(dp[nm][j],dp[mask][i]+dist[i][j]);}
  }
  let min=INF;
  for(let i=1;i<n;i++)if(dp[FULL][i]!==INF)min=Math.min(min,dp[FULL][i]+dist[i][0]);
  return min;
}

function iterateSubmasksImpl(mask) {
  const s=[];
  for(let sub=mask;sub>0;sub=(sub-1)&mask)s.push(sub);
  s.push(0);
  return s;
}

