function knightProbabilityImpl(n,k,row,col){
  const MOVES=[[-2,-1],[-2,1],[-1,-2],[-1,2],[1,-2],[1,2],[2,-1],[2,1]];
  let curr=Array.from({length:n},()=>new Array(n).fill(0));
  curr[row][col]=1.0;
  for(let move=0;move<k;move++){
    const next=Array.from({length:n},()=>new Array(n).fill(0));
    for(let r=0;r<n;r++)for(let c=0;c<n;c++){
      if(curr[r][c]===0)continue;
      for(const[dr,dc]of MOVES){const nr=r+dr,nc=c+dc;if(nr>=0&&nr<n&&nc>=0&&nc<n)next[nr][nc]+=curr[r][c]/8.0;}
    }
    curr=next;
  }
  return curr.reduce((s,row)=>s+row.reduce((t,v)=>t+v,0),0);
}

function new21GameImpl(n, k, maxPts) {
  if (k === 0 || n >= k + maxPts) return 1.0;
  const dp = new Array(n + maxPts + 1).fill(0);
  dp[0] = 1.0;
  let windowSum = 1.0, result = 0;
  for (let i = 1; i <= n + maxPts; i++) {
    dp[i] = windowSum / maxPts;
    if (i < k) windowSum += dp[i];
    if (i >= k && i <= n) result += dp[i];
    if (i >= maxPts) windowSum -= dp[i - maxPts];
  }
  return result;
}

