function classifyHardDP(signal) {
  if(signal.includes('palindrome')||signal.includes('cuts'))return'String Palindrome DP';
  if(signal.includes('adjacent')||signal.includes('cameras')||signal.includes('tree'))return'Tree DP';
  if(signal.includes('n<=20')||signal.includes('subset')||signal.includes('visit all'))return'Bitmask DP';
  if(signal.includes('count in range')||signal.includes('digit'))return'Digit DP';
  if(signal.includes('probability')||signal.includes('expected'))return'Probability DP';
  return'Unknown';
}

function module1Summary() {
  return{
    total:MODULE1_NC150.length,
    nc150:MODULE1_NC150.filter(p=>p.nc150).length,
    types:[...new Set(MODULE1_NC150.map(p=>p.type))]
  };
}
